env = dict(os.environ, GBRAIN_HOME="/harness-state")
cmd = ["/harness-state/.gbrain/hook-launcher/gbrain-hook", "/harness-state/.local/bin/gbrain",
       "serve", "--surface", "starter", "--advertise", "verbs"]
p = subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL,
                     env=env, text=True, cwd="/harness-state")

def send(m):
    p.stdin.write(json.dumps(m) + "\n"); p.stdin.flush()

def recv(id_):
    while True:
        line = p.stdout.readline()
        if not line:
            raise RuntimeError("server closed stdout")
        try:
            m = json.loads(line)
        except ValueError:
            continue
        if m.get("id") == id_:
            return m

def call(id_, name, args):
    send({"jsonrpc": "2.0", "id": id_, "method": "tools/call", "params": {"name": name, "arguments": args}})
    r = recv(id_)
    res = r["result"]
    return res.get("isError"), json.loads(res["content"][0]["text"])

send({"jsonrpc": "2.0", "id": 1, "method": "initialize", "params": {"protocolVersion": "2025-06-18", "capabilities": {}, "clientInfo": {"name": "hermes-verify", "version": "1"}}})
